    with open(csv_file, 'w', newline='') as f:
        writer = csv.writer(f)
        writer.writerow(['directory', 'file_count'])

        for root, dirs, files in os.walk(log_dir):
            dir_name = os.path.basename(root)
            count = len(files)

            writer.writerow([dir_name, count])

